    private static final ConcurrentHashMap<String, StoreState> STORES_BY_PATH = new ConcurrentHashMap<>();

    private final RuleViolationFileNameStrategy ruleViolationFileNameStrategy;
    private final boolean strategyWasPassedToConstructor;
    private boolean deriveExistingNames;

    private boolean storeCreationAllowed;
    private boolean storeUpdateAllowed;
    private IntegrityMode integrityMode;
    private StoreState storeState;
    private Path storeFolder;
    private Properties storedRules;

    /**
     * Creates a standard store that names rule violation files by random {@link UUID}s.
     *
     * @see #TextFileBasedViolationStore(RuleViolationFileNameStrategy)
     */
    public TextFileBasedViolationStore() {
        ruleViolationFileNameStrategy = new RandomRuleViolationFileNameStrategy();
        strategyWasPassedToConstructor = false;
        deriveExistingNames = false;
    }

    /**
     * Creates a store with a custom strategy for rule violation file naming.
     *
     * @param ruleViolationFileNameStrategy controls how the individual violation file name is derived
     */
    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
        if (ruleViolationFileNameStrategy == null) {
            throw new NullPointerException("ruleViolationFileNameStrategy must not be null");
        }
        this.ruleViolationFileNameStrategy = ruleViolationFileNameStrategy;
        strategyWasPassedToConstructor = true;
        deriveExistingNames = true;
    }

    @Override
    public void initialize(Properties properties) {
        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
        integrityMode = IntegrityMode.from(properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT));
        if (integrityMode == IntegrityMode.REPAIR && !storeUpdateAllowed) {
            throw new StoreInitializationFailedException(String.format(
                    "Integrity mode 'repair' requires %s=true", ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }

        RuleViolationFileNameStrategy effectiveStrategy = resolveFileNameStrategy(properties);
        // A configured strategy is selected before the folder is touched. This is important for
        // custom stores: even a default inherited by Properties is an explicit conflict.
        if (effectiveStrategy != ruleViolationFileNameStrategy) {
            // The field is final, so the selected strategy is kept in the per-initialization field
            // below. This branch only documents the distinction; the actual strategy is selected
            // by strategyForCurrentInitialization().
        }

        Path configuredFolder;
        try {
            configuredFolder = Paths.get(properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT))
                    .toAbsolutePath().normalize();
        } catch (InvalidPathException e) {
            throw new StoreInitializationFailedException("Invalid store path", e);
        }

        StoreState state = getStoreState(configuredFolder);
        synchronized (state.lock) {
            state.folder = configuredFolder;
            state.index = configuredFolder.resolve(STORED_RULES_FILE_NAME).normalize();
            prepareFolder(state);

            boolean indexExists = Files.exists(state.index, LinkOption.NOFOLLOW_LINKS);
            if (indexExists && !isDirectRegularFile(state.index)) {
                throw new StoreInitializationFailedException(String.format(
                        "The violation store index must be a regular file directly in the store folder: %s", state.index));
            }
            if (!indexExists && !storeCreationAllowed) {
                throw new StoreInitializationFailedException(String.format(
                        "Creating new violation store is disabled (enable by configuration %s.%s=true)",
                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
            }

