    private void requireInitialized() {
        if (storeState == null) {
            throw new IllegalStateException("Violation store has not been initialized");
        }
    }

    private Properties reloadCurrentProperties() {
        return loadRulesFrom(storeState.index);
    }

    private static void syncIndex(StoreState state, Properties properties) {
        Path temporary = temporaryPath(state, STORED_RULES_FILE_NAME);
        try {
            try (OutputStream outputStream = Files.newOutputStream(temporary, StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE)) {
                properties.store(outputStream, "");
            }
            moveReplacing(temporary, state.index);
        } catch (IOException e) {
            throw new StoreUpdateFailedException(e);
        } finally {
            deleteQuietly(temporary);
        }
    }

    private static Path temporaryPath(StoreState state, String baseName) {
        return state.realFolder.resolve("." + baseName + "." + UUID.randomUUID() + ".tmp");
    }

    private static void moveReplacing(Path source, Path target) throws IOException {
        try {
            Files.move(source, target, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
        } catch (IOException atomicMoveUnsupported) {
            Files.move(source, target, StandardCopyOption.REPLACE_EXISTING);
        }
    }

    private IntegrityResult inspect(StoreState state, Properties properties, RuleViolationFileNameStrategy strategy) {
        List<Entry> entries = new ArrayList<>();
        for (String description : properties.stringPropertyNames()) {
            entries.add(new Entry(description, properties.getProperty(description)));
        }
        entries.sort(Comparator.comparing(entry -> entry.description));

        IntegrityResult result = new IntegrityResult(properties, entries);
        for (Entry entry : entries) {
            entry.path = parsePath(state, entry.fileName, true);
            entry.target = entry.path == null ? null : regularTarget(entry.path);
            entry.broken = entry.path == null || entry.target == null || !state.realFolder.equals(entry.target.getParent()) || isIndex(state, entry.path);
            if (!entry.broken) {
                try {
                    entry.resolved = readLines(entry.path).isEmpty();
                } catch (RuntimeException e) {
                    entry.broken = true;
                }
            }
            if (deriveExistingNames) {
                entry.derivedName = createRequiredFileNameForInitialization(strategy, entry.description);
                entry.misplaced = !entry.fileName.equals(entry.derivedName);
            }
        }

        for (Entry entry : entries) {
            for (Entry other : entries) {
                if (entry != other && (entry.fileName.equals(other.fileName) || sameFile(entry.target, other.target))) {
                    entry.shared = true;
                }
                if (entry != other && entry.derivedName != null && entry.derivedName.equals(other.derivedName)) {
                    entry.colliding = true;
                }
            }
            if (entry.misplaced) {
                entry.occupied = derivedIsOccupied(state, entry, entries);
            }
        }

        result.unownedFiles.addAll(findUnownedFiles(state, entries));
        for (Entry entry : entries) {
            if (entry.broken) result.broken.add(entry);
            if (entry.resolved) result.resolved.add(entry);
            if (entry.shared) result.shared.add(entry);
            if (entry.misplaced) result.misplaced.add(entry);
            if (entry.colliding) result.colliding.add(entry);
            if (entry.occupied) result.occupied.add(entry);
        }
        return result;
    }

    private String createRequiredFileNameForInitialization(RuleViolationFileNameStrategy strategy, String description) {
        String result;
        try {
            result = strategy.createRuleFileName(description);
        } catch (RuntimeException e) {
            throw new StoreInitializationFailedException("Could not derive a rule violation file name", e);
        }
        if (result == null || result.isEmpty()) {
            throw new StoreInitializationFailedException(
                    "The RuleViolationFileNameStrategy yielded no file name for rule '" + description + "'");
        }
        return result;
    }

    private boolean derivedIsOccupied(StoreState state, Entry entry, List<Entry> entries) {
        if (entry.fileName.equals(entry.derivedName)) {
            return false;
        }
        for (Entry other : entries) {
            if (other != entry && entry.derivedName.equals(other.fileName)) {
                return true;
            }
        }
        Path derived = parsePath(state, entry.derivedName, true);
        if (derived == null || !isLexicallyDirectChild(state, derived) || isIndex(state, derived)) {
            return true;
        }
        return Files.exists(derived, LinkOption.NOFOLLOW_LINKS);
    }

    private List<String> findUnownedFiles(StoreState state, List<Entry> entries) {
        List<String> result = new ArrayList<>();
        try (DirectoryStream<Path> files = Files.newDirectoryStream(state.realFolder)) {
            for (Path file : files) {
                if (!Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS) || sameFile(file, state.index)) {
                    continue;
                }
                boolean owned = false;
                for (Entry entry : entries) {
                    if (sameFile(file, entry.target)) {
                        owned = true;
                        break;
                    }
                }
                if (!owned) {
                    result.add(file.getFileName().toString());
                }
            }
        } catch (IOException e) {
            throw new StoreInitializationFailedException("Cannot inspect violation store folder", e);
        }
        Collections.sort(result);
        return result;
    }

    private String failureReport(StoreState state, IntegrityResult result) {
        StringBuilder report = new StringBuilder();
        report.append("Violation store integrity check failed at ").append(state.index)
                .append(" (default.allowStoreUpdate=").append(storeUpdateAllowed).append("): ");
        appendEntries(report, "broken", result.broken);
        appendEntries(report, "resolved", result.resolved);
        appendEntries(report, "shared", result.shared);
        if (!result.unownedFiles.isEmpty()) {
            if (report.charAt(report.length() - 1) != ' ') report.append("; ");
            report.append("unowned files ").append(result.unownedFiles);
        }
        appendEntries(report, "misplaced", result.misplaced);
        appendEntries(report, "colliding", result.colliding);
        appendEntries(report, "occupied", result.occupied);
        return report.toString();
    }

    private void appendEntries(StringBuilder report, String label, List<Entry> entries) {
        if (!entries.isEmpty()) {
            if (report.charAt(report.length() - 1) != ' ') report.append("; ");
            report.append(label).append(" ");
            List<String> values = new ArrayList<>();
            for (Entry entry : entries) {
                values.add(entry.description + " -> " + entry.fileName);
            }
            report.append(values);
        }
    }

