    private Path validateSavePath(StoreState state, String fileName, boolean existingEntry,
            Properties current, String description) {
        Path path = parsePath(state, fileName, false);
        if (path == null || !isLexicallyDirectChild(state, path) || isIndex(state, path)) {
            throw new StoreUpdateFailedException(String.format(
                    "Cannot store rule '%s': file name '%s' does not lead directly into the store folder",
                    description, fileName));
        }

        boolean somethingExists = Files.exists(path, LinkOption.NOFOLLOW_LINKS);
        if (somethingExists) {
            if (!Files.isRegularFile(path)) {
                throw new StoreUpdateFailedException(String.format(
                        "Cannot store rule '%s': file name '%s' does not name a regular file",
                        description, fileName));
            }
            Path real = realPath(path);
            if (real == null || !state.realFolder.equals(real.getParent()) || isIndex(state, path)) {
                throw new StoreUpdateFailedException(String.format(
                        "Cannot store rule '%s': file name '%s' does not lead directly into the store folder",
                        description, fileName));
            }
            if (!existingEntry) {
                throw new StoreUpdateFailedException(String.format(
                        "Cannot store rule '%s': file name '%s' names a file not recorded by its own index entry",
                        description, fileName));
            }
        } else if (Files.isSymbolicLink(path)) {
            throw new StoreUpdateFailedException(String.format(
                    "Cannot store rule '%s': file name '%s' is a dangling symbolic link",
                    description, fileName));
        }

        // A custom strategy must not silently overwrite another entry's file through an alias.
        if (!existingEntry && isRecordedByAnotherFile(current, description, fileName, state)) {
            throw new StoreUpdateFailedException(String.format(
                    "Cannot store rule '%s': file name '%s' is already recorded by another entry",
                    description, fileName));
        }
        return path;
    }

    private boolean isRecordedByAnotherFile(Properties current, String description, String fileName, StoreState state) {
        Path candidate = parsePath(state, fileName, false);
        for (String otherDescription : current.stringPropertyNames()) {
            if (!otherDescription.equals(description)) {
                String otherName = current.getProperty(otherDescription);
                if (fileName.equals(otherName)) {
                    return true;
                }
                Path other = parsePath(state, otherName, false);
                if (candidate != null && other != null && sameFile(candidate, other)) {
                    return true;
                }
            }
        }
        return false;
    }

