    private Path parsePath(StoreState state, String fileName) {
        try {
            if (fileName == null || fileName.indexOf('\0') >= 0) {
                return null;
            }
            Path path = Paths.get(fileName);
            return state.folder.resolve(path).normalize();
        } catch (InvalidPathException | NullPointerException e) {
            return null;
        }
    }

    private boolean isLexicallyDirectChild(StoreState state, Path path) {
        Path normalizedFolder = state.folder.normalize();
        return normalizedFolder.equals(path.getParent());
    }

    private boolean isIndex(StoreState state, Path path) {
        if (path == null) return false;
        if (state.index.normalize().equals(path.normalize())) return true;
        return sameFile(path, state.index);
    }

