    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
    private static final String FILE_NAMES_PROPERTY_NAME = "default.fileNames";
    private static final String INTEGRITY_PROPERTY_NAME = "default.integrity";
    private static final String INTEGRITY_DEFAULT = "ignore";

    private static final Pattern DESCRIPTION_WORD = Pattern.compile("(?<![A-Za-z0-9])[A-Za-z0-9]{4,120}(?![A-Za-z0-9])");
    private static final Pattern ONLY_LINE_BREAKS = Pattern.compile("(?:\\r\\n|\\n|\\r)*");

    /*
     * This is deliberately process-local. The file format is still safe for a reader in another
     * process because index writes are atomic, while this lock is what prevents this process from
     * inspecting a half-written violation file.
     */
    private static final ConcurrentHashMap<String, StoreState> STORES_BY_PATH = new ConcurrentHashMap<>();

    private final RuleViolationFileNameStrategy ruleViolationFileNameStrategy;
    private final boolean strategyWasPassedToConstructor;
    private boolean deriveExistingNames;

    private boolean storeCreationAllowed;
    private boolean storeUpdateAllowed;
    private IntegrityMode integrityMode;
    private StoreState storeState;
    private Properties storedRules;

    /**
     * Creates a standard store that names rule violation files by random {@link UUID}s.
     *
     * @see #TextFileBasedViolationStore(RuleViolationFileNameStrategy)
     */
    public TextFileBasedViolationStore() {
        ruleViolationFileNameStrategy = new RandomRuleViolationFileNameStrategy();
        strategyWasPassedToConstructor = false;
        deriveExistingNames = false;
    }

    /**
     * Creates a store with a custom strategy for rule violation file naming.
     *
     * @param ruleViolationFileNameStrategy controls how the individual violation file name is derived
     */
    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
        if (ruleViolationFileNameStrategy == null) {
            throw new NullPointerException("ruleViolationFileNameStrategy must not be null");
        }
        this.ruleViolationFileNameStrategy = ruleViolationFileNameStrategy;
        strategyWasPassedToConstructor = true;
        deriveExistingNames = true;
    }

    @Override
    public void initialize(Properties properties) {
        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
        integrityMode = IntegrityMode.from(properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT));
        if (integrityMode == IntegrityMode.REPAIR && !storeUpdateAllowed) {
            throw new StoreInitializationFailedException(String.format(
                    "Integrity mode 'repair' requires %s=true", ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }

        // A configured strategy is selected before the folder is touched. This is important for
        // custom stores: even a default inherited by Properties is an explicit conflict.
        RuleViolationFileNameStrategy effectiveStrategy = resolveFileNameStrategy(properties);

        Path configuredFolder;
        try {
            configuredFolder = Paths.get(properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT))
                    .toAbsolutePath().normalize();
        } catch (InvalidPathException e) {
            throw new StoreInitializationFailedException("Invalid store path", e);
        }

        StoreState state = getStoreState(configuredFolder);
        synchronized (state.lock) {
            state.folder = configuredFolder;
            state.index = configuredFolder.resolve(STORED_RULES_FILE_NAME).normalize();
            prepareFolder(state);

            boolean indexExists = Files.exists(state.index, LinkOption.NOFOLLOW_LINKS);
            if (indexExists && !isDirectRegularFile(state.index)) {
                throw new StoreInitializationFailedException(String.format(
                        "The violation store index must be a regular file directly in the store folder: %s", state.index));
            }
            if (!indexExists && !storeCreationAllowed) {
                throw new StoreInitializationFailedException(String.format(
                        "Creating new violation store is disabled (enable by configuration %s.%s=true)",
                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
            }

            Properties loaded = indexExists ? loadRulesFrom(state.index) : new Properties();
            IntegrityResult result = integrityMode == IntegrityMode.IGNORE
                    ? IntegrityResult.empty(loaded)
                    : inspect(state, loaded, effectiveStrategy);

            if (integrityMode == IntegrityMode.FAIL && !result.isClean()) {
                throw new StoreInitializationFailedException(failureReport(state, result));
            }

            if (integrityMode == IntegrityMode.REPAIR) {
                repair(state, loaded, result);
                if (!indexExists) {
                    syncIndexDuringInitialization(state, loaded);
                }
            } else if (!indexExists) {
                // In fail mode this is deliberately delayed until after the scan. A rejected
                // initialization must not leave a newly created index behind.
                syncIndexDuringInitialization(state, loaded);
            }

            state.properties = loaded;
            storeState = state;
            storedRules = loaded;
            log.trace("Initialized {} at {}", TextFileBasedViolationStore.class.getSimpleName(), state.index);
        }
    }

    /* The strategy selected from properties is needed by save and integrity operations. */
    private RuleViolationFileNameStrategy strategyForCurrentInitialization;

    private RuleViolationFileNameStrategy resolveFileNameStrategy(Properties properties) {
        if (strategyWasPassedToConstructor) {
            if (properties.getProperty(FILE_NAMES_PROPERTY_NAME) != null) {
                throw new StoreInitializationFailedException(String.format(
                        "%s cannot be configured for a store constructed with a RuleViolationFileNameStrategy",
                        FILE_NAMES_PROPERTY_NAME));
            }
            deriveExistingNames = true;
            strategyForCurrentInitialization = ruleViolationFileNameStrategy;
            return ruleViolationFileNameStrategy;
        }

        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME, "random");
        if ("random".equals(configured)) {
            deriveExistingNames = false;
            strategyForCurrentInitialization = ruleViolationFileNameStrategy;
            return ruleViolationFileNameStrategy;
        }
        if ("description".equals(configured)) {
            deriveExistingNames = true;
            strategyForCurrentInitialization = new DescriptionRuleViolationFileNameStrategy();
            return strategyForCurrentInitialization;
        }
        try {
            Class<?> type = Class.forName(configured);
            Class<?> type = Class.forName(configured);
            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(type)) {
                throw new IllegalArgumentException("does not implement " + RuleViolationFileNameStrategy.class.getName());
            }
            @SuppressWarnings("unchecked")
            Class<? extends RuleViolationFileNameStrategy> strategyType =
                    (Class<? extends RuleViolationFileNameStrategy>) type;
            Constructor<? extends RuleViolationFileNameStrategy> constructor = strategyType.getConstructor();
            strategyForCurrentInitialization = constructor.newInstance();
            deriveExistingNames = true;
            return strategyForCurrentInitialization;
        } catch (ClassNotFoundException | NoSuchMethodException | InstantiationException | IllegalAccessException |
                 InvocationTargetException | ClassCastException | IllegalArgumentException e) {
            throw new StoreInitializationFailedException(String.format(
                    "Could not instantiate %s configured by %s=%s; expected a public no-argument implementation",
                    RuleViolationFileNameStrategy.class.getSimpleName(), FILE_NAMES_PROPERTY_NAME, configured), e);
        }
    }

    private static StoreState getStoreState(Path folder) {
        String key;
        try {
            key = folder.toFile().getCanonicalPath();
        } catch (IOException e) {
            key = folder.toString();
        }
        final String stateKey = key;
        return STORES_BY_PATH.computeIfAbsent(stateKey, ignored -> new StoreState());
    }

    private void prepareFolder(StoreState state) {
        try {
            if (!Files.exists(state.folder)) {
                if (!storeCreationAllowed) {
                    return;
                }
                Files.createDirectories(state.folder);
            }
            if (!Files.isDirectory(state.folder)) {
                throw new StoreInitializationFailedException(String.format(
                        "The violation store path is not a folder: %s", state.folder));
            }
            state.realFolder = state.folder.toRealPath();
        } catch (IOException e) {
            throw new StoreInitializationFailedException(String.format(
                    "Cannot create or access violation store folder %s", state.folder), e);
        }
    }

    private boolean isDirectRegularFile(Path path) {
        return Files.isRegularFile(path, LinkOption.NOFOLLOW_LINKS);
    }

    private static Properties loadRulesFrom(Path file) {
        Properties result = new Properties();
        try (FileInputStream inputStream = new FileInputStream(file.toFile())) {
            result.load(inputStream);
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
        return result;
    }

    @Override
    public boolean contains(ArchRule rule) {
        requireInitialized();
        synchronized (storeState.lock) {
            storedRules = reloadCurrentProperties();
            storeState.properties = storedRules;
            return storedRules.containsKey(normalizeRuleDescription(rule.getDescription()));
        }
    }

    @Override
    public void save(ArchRule rule, List<String> violations) {
        requireInitialized();
        synchronized (storeState.lock) {
            if (!storeUpdateAllowed) {
                throw new StoreUpdateFailedException(String.format(
                        "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
            }

            Properties current = reloadCurrentProperties();
            String ruleDescription = rule.getDescription();
            String description = normalizeRuleDescription(ruleDescription);
            String existingFileName = current.getProperty(description);

            // A repair-mode empty save is a deletion operation. Unknown empty rules are a no-op,
            // and consequently do not need a name from a strategy at all.
            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR && existingFileName == null) {
                storedRules = current;
                storeState.properties = current;
                return;
            }

            String generatedFileName = null;
            if (existingFileName == null || !violations.isEmpty() || integrityMode != IntegrityMode.REPAIR) {
                generatedFileName = createRequiredFileName(ruleDescription, false);
            }
            String fileName = existingFileName != null ? existingFileName : generatedFileName;

            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
                Path file = validateSavePath(storeState, fileName, true, current, description);
                if (!isSharedWithAnotherEntry(storeState, current, description, fileName, file)) {
                    deleteEntryFile(storeState, file);
                }
                current.remove(description);
                syncIndex(storeState, current);
                storedRules = current;
                storeState.properties = current;
                return;
            }

            Path file = validateSavePath(storeState, fileName, existingFileName != null, current, description);
            boolean newEntry = existingFileName == null;
            boolean newFile = newEntry && !Files.exists(file, LinkOption.NOFOLLOW_LINKS);
            writeViolations(storeState, file, violations, newFile);

            if (newEntry) {
                current.setProperty(description, fileName);
                try {
                    syncIndex(storeState, current);
                } catch (RuntimeException e) {
                    if (newFile) {
                        deleteQuietly(file);
                    }
                    throw e;
                }
            }
            storedRules = current;
            storeState.properties = current;
        }
    }

    private String createRequiredFileName(String description, boolean initialization) {
        String result;
        try {
            result = strategyForCurrentInitialization.createRuleFileName(description);
        } catch (RuntimeException e) {
            if (initialization) {
                throw new StoreInitializationFailedException("Could not derive a rule violation file name", e);
            }
            throw e;
        }
        if (result == null || result.isEmpty()) {
            String message = "The RuleViolationFileNameStrategy yielded no file name for rule '" + description + "'";
            if (initialization) {
                throw new StoreInitializationFailedException(message);
            }
            throw new StoreUpdateFailedException(message);
        }
        return result;
    }

    private Path validateSavePath(StoreState state, String fileName, boolean existingEntry,
            Properties current, String description) {
        Path path = parsePath(state, fileName);
        if (path == null || !isLexicallyDirectChild(state, path) || isIndex(state, path)) {
            throw new StoreUpdateFailedException(String.format(
                    "Cannot store rule '%s': file name '%s' does not lead directly into the store folder",
                    description, fileName));
        }

        boolean somethingExists = Files.exists(path, LinkOption.NOFOLLOW_LINKS);
        if (somethingExists) {
            if (!Files.isRegularFile(path)) {
                throw new StoreUpdateFailedException(String.format(
                        "Cannot store rule '%s': file name '%s' does not name a regular file",
                        description, fileName));
            }
            Path real = realPath(path);
            if (real == null || !state.realFolder.equals(real.getParent()) || isIndex(state, path)) {
                throw new StoreUpdateFailedException(String.format(
                        "Cannot store rule '%s': file name '%s' does not lead directly into the store folder",
                        description, fileName));
            }
            if (!existingEntry) {
                throw new StoreUpdateFailedException(String.format(
                        "Cannot store rule '%s': file name '%s' names a file not recorded by its own index entry",
                        description, fileName));
            }
        } else if (Files.isSymbolicLink(path)) {
            throw new StoreUpdateFailedException(String.format(
                    "Cannot store rule '%s': file name '%s' is a dangling symbolic link",
                    description, fileName));
        }

        // A custom strategy must not silently overwrite another entry's file through an alias.
        if (!existingEntry && isRecordedByAnotherFile(current, description, fileName, state)) {
            throw new StoreUpdateFailedException(String.format(
                    "Cannot store rule '%s': file name '%s' is already recorded by another entry",
                    description, fileName));
        }
        return path;
    }

    private boolean isRecordedByAnotherFile(Properties current, String description, String fileName, StoreState state) {
        Path candidate = parsePath(state, fileName);
        for (String otherDescription : current.stringPropertyNames()) {
            if (!otherDescription.equals(description)) {
                String otherName = current.getProperty(otherDescription);
                if (fileName.equals(otherName)) {
                    return true;
                }
                Path other = parsePath(state, otherName);
                if (candidate != null && other != null && sameFile(candidate, other)) {
                    return true;
                }
            }
        }
        return false;
    }

    private void writeViolations(StoreState state, Path file, List<String> violations, boolean newFile) {
        StringBuilder builder = new StringBuilder();
        for (String violation : violations) {
            builder.append(escape(violation)).append('\n');
        }
        byte[] bytes = builder.toString().getBytes(StandardCharsets.UTF_8);
        Path temporary = null;
        try {
            if (newFile) {
                temporary = temporaryPath(state, file.getFileName().toString());
                Files.write(temporary, bytes, StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE);
                moveReplacing(temporary, file);
                temporary = null;
            } else {
                // Writing through the index path is intentional: if it is a symbolic or hard
                // link, save updates the file it leads to rather than replacing the link.
                Files.write(file, bytes, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE);
            }
        } catch (IOException e) {
            throw new StoreUpdateFailedException(e);
        } finally {
            if (temporary != null) {
                deleteQuietly(temporary);
            }
        }
    }

    private String escape(String violation) {
        return violation.replace("\n", "\\\n");
    }

    private String unescape(String violation) {
        return violation.replace("\\\n", "\n");
    }

    @Override
    public List<String> getViolations(ArchRule rule) {
        requireInitialized();
        synchronized (storeState.lock) {
            storedRules = reloadCurrentProperties();
            storeState.properties = storedRules;
            String ruleDetailsFileName = storedRules.getProperty(normalizeRuleDescription(rule.getDescription()));
            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
            Path file = parsePath(storeState, ruleDetailsFileName);
            if (file == null) {
                throw new StoreReadException(new IOException("Invalid stored rule file name"));
            }
            return readLines(file);
        }
    }

    private List<String> readLines(Path file) {
        String violationsText;
        try {
            violationsText = new String(Files.readAllBytes(file), StandardCharsets.UTF_8);
        } catch (IOException e) {
            throw new StoreReadException(e);
        }
        if (violationsText.isEmpty() || ONLY_LINE_BREAKS.matcher(violationsText).matches()) {
            return Collections.emptyList();
        }

        List<String> result = new ArrayList<>();
        int start = 0;
        for (int i = 0; i < violationsText.length(); i++) {
            if (violationsText.charAt(i) == '\n' && (i == 0 || violationsText.charAt(i - 1) != '\\')) {
                String line = violationsText.substring(start, i);
                // External stores commonly use CRLF. A CR in the middle of a violation is not
                // normalized or removed; only the CR belonging to this record's line ending is.
                if (line.endsWith("\r")) {
                    line = line.substring(0, line.length() - 1);
                }
                if (!line.isEmpty()) {
                    result.add(unescape(line));
                }
                start = i + 1;
            }
        }
        if (start < violationsText.length()) {
            String line = violationsText.substring(start);
            if (!line.isEmpty()) {
                result.add(unescape(line));
            }
        }
        return result;
    }

